<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { usePoints } from '../usePoints'
import { useStaffWallet } from '../useStaffWallet'
import WalletStaffCustomerPicker from '../components/WalletStaffCustomerPicker.vue'
import WalletPointsEntries from '../components/WalletPointsEntries.vue'
defineProps<{embedded?:boolean}>()
const emit=defineEmits<{'busy-change':[busy:boolean]}>()
const {t}=useI18n(),{store,customer,can,context}=useStaffWallet(),points=usePoints(store,false,computed(()=>customer.value?.id),()=>can('wallet.points.view')),{account,entries,busy,error,ready,more}=points
const kind=ref<'grants'|'deductions'|'redemptions'>(can('wallet.points.grant')?'grants':can('wallet.points.adjust')?'deductions':'redemptions'),quantity=ref(''),reason=ref(''),note=ref(''),externalReference=ref(''),redemptionDescription=ref(''),reverseId=ref('')
watch(busy,value=>emit('busy-change',value),{immediate:true,flush:'sync'})
watch([store,()=>customer.value?.id],()=>{quantity.value='';reason.value='';note.value='';externalReference.value='';redemptionDescription.value='';reverseId.value=''})
const canMutate=computed(()=>['wallet.points.grant','wallet.points.adjust','wallet.points.redeem'].some(can))
const allowed=computed(()=>can(kind.value==='grants'?'wallet.points.grant':kind.value==='deductions'?'wallet.points.adjust':'wallet.points.redeem'))
async function submit(){if(!allowed.value||!/^\d+$/.test(quantity.value)||Number(quantity.value)<1)return;await points.command(kind.value,{quantity:Number(quantity.value),note:note.value,...(kind.value==='redemptions'?{redemptionDescription:redemptionDescription.value,externalReference:externalReference.value}:kind.value==='grants'?{reason:reason.value,externalReference:externalReference.value}:{reason:reason.value})});if(!error.value){quantity.value='';reason.value='';note.value='';externalReference.value='';redemptionDescription.value=''}}
async function reverse(){if(!can('wallet.points.reverse')||!reason.value.trim())return;await points.command('reverse',{reason:reason.value},reverseId.value);if(!error.value)reverseId.value=''}
</script>
<template><section v-if="!embedded" class="wallet-page-heading"><h2>{{t('wallet.marketing.points')}}</h2><button :disabled="busy" @click="points.refresh()">{{t('wallet.refresh')}}</button></section><p class="wallet-warning">{{t('wallet.marketing.pointsHint')}}</p><p v-if="!can('wallet.points.view')" class="wallet-empty">{{t('wallet.noRights')}}</p><template v-else><WalletStaffCustomerPicker :allow-scan="false" :open-account="false" :disabled="busy" /><p v-if="points.stale.value" class="wallet-warning">{{t('wallet.marketing.stale')}}</p><p v-if="error" class="wallet-error" role="alert">{{error}}</p><p v-if="busy&&!ready" role="status">{{t('wallet.loading')}}</p><template v-if="account"><section class="wallet-card"><h3>{{t('wallet.marketing.balance')}}: {{account.balance}}</h3></section><form v-if="context?.transactionsEnabled&&canMutate" class="wallet-form" @submit.prevent="submit"><select v-model="kind"><option v-if="can('wallet.points.grant')" value="grants">{{t('wallet.marketing.grant')}}</option><option v-if="can('wallet.points.adjust')" value="deductions">{{t('wallet.marketing.deduction')}}</option><option v-if="can('wallet.points.redeem')" value="redemptions">{{t('wallet.marketing.redemption')}}</option></select><label>{{t('wallet.marketing.quantity')}}<input v-model="quantity" type="number" min="1" max="1000000000" step="1" inputmode="numeric" required></label><label v-if="kind!=='redemptions'">{{t('wallet.marketing.reason')}}<input v-model.trim="reason" required maxlength="200"></label><label v-if="kind==='redemptions'">{{t('wallet.marketing.description')}}<input v-model.trim="redemptionDescription" required maxlength="500"></label><label>{{t('wallet.marketing.note')}}<textarea v-model.trim="note" maxlength="500" /></label><label v-if="kind!=='deductions'">{{t('wallet.marketing.reference')}}<input v-model.trim="externalReference" maxlength="160"></label><button :disabled="busy||!allowed||points.stale.value">{{t('wallet.marketing.confirm')}}</button></form><form v-if="reverseId" class="wallet-form" @submit.prevent="reverse"><p>{{reverseId}}</p><label>{{t('wallet.marketing.reason')}}<input v-model.trim="reason" required maxlength="200"></label><button :disabled="busy">{{t('wallet.marketing.reverse')}}</button><button type="button" @click="reverseId=''">{{t('wallet.marketing.cancel')}}</button></form><p v-if="ready&&!entries.length" class="wallet-empty">{{t('wallet.empty')}}</p><WalletPointsEntries :entries="entries" :timezone="context?.store.timezone??'Asia/Singapore'" :can-reverse="can('wallet.points.reverse')" :disabled="busy||points.stale.value" @reverse="reverseId=$event" /><button v-if="more" :disabled="busy" @click="points.refresh(true)">{{t('wallet.marketing.next')}}</button></template></template></template>
